const requests = [0, 10, 20, 30, 60];
const limit = 3;
const windowSeconds = 60;
let accepted = [];
for (const now of requests) {
  accepted = accepted.filter(time => now - time < windowSeconds);
  if (accepted.length < limit) {
    accepted.push(now);
    console.log(now + "s allow");
  } else {
    console.log(now + "s wait");
  }
}
